BUSINESS_HTML=r'''<!doctype html><html><head><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#07111f"><title>Panther Peptides Command Center</title><style>:root{--panel:#0b1727;--line:#203c59;--text:#f2f7fc;--muted:#8ea8c1;--green:#39d49d;--amber:#f2b84b;--red:#ff7185;--blue:#4b9dff}*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at 50% -20%,#17375c 0,#07111f 35%,#040910 100%);color:var(--text);font:15px system-ui,-apple-system,sans-serif;min-height:100vh}.wrap{max-width:1680px;margin:auto;padding:22px}.top,.head,.tabs{display:flex;justify-content:space-between;align-items:center;gap:14px;margin-bottom:18px}.brand{display:flex;align-items:center;gap:14px}.logo{width:50px;height:50px;border-radius:15px;background:linear-gradient(135deg,#3f91ff,#53dfc0);display:grid;place-items:center;font-weight:900;color:#06101d}.brand h1,.card h2{margin:0}.muted,.notice,small{color:var(--muted)}.nav,.actions,.filters{display:flex;gap:8px;flex-wrap:wrap}.btn{border:1px solid #2d4c6c;background:#10223a;color:#eaf4ff;padding:10px 13px;border-radius:11px;font-weight:750;cursor:pointer;text-decoration:none}.btn.green{background:#123c33;border-color:#236d59}.btn.amber{background:#3b2c10;border-color:#775b20}.btn.primary{background:#164b88;border-color:#2e79c8}.btn.active{outline:2px solid #4b9dff}.banner{border:1px solid #285f51;background:#0d2923;color:#c8f5e4;padding:11px 15px;border-radius:13px;margin-bottom:18px}.metrics{display:grid;grid-template-columns:repeat(6,1fr);gap:12px;margin-bottom:18px}.metric,.card{background:linear-gradient(180deg,rgba(15,32,53,.98),rgba(9,22,38,.98));border:1px solid var(--line);border-radius:18px}.metric{padding:17px}.metric b{display:block;font-size:26px;margin-top:6px}.metric span{color:var(--muted);font-size:12px}.grid{display:grid;grid-template-columns:minmax(0,1.7fr) minmax(350px,.7fr);gap:18px}.card{padding:20px}.tablewrap{overflow:auto;border:1px solid #1f3852;border-radius:14px}table{width:100%;border-collapse:collapse;min-width:900px}th,td{text-align:left;padding:12px;border-bottom:1px solid #1d354e;vertical-align:top}th{font-size:12px;text-transform:uppercase;color:#91acc6;background:#0a1727}.pill{display:inline-block;border:1px solid #31516f;border-radius:999px;padding:5px 9px;font-size:12px}.pill.available,.pill.approved,.pill.on_file{color:#bdf5df;border-color:#286b59;background:#0d2b24}.pill.quarantine,.pill.hold,.pill.blocked{color:#ffd278;border-color:#76591e;background:#2b210d}.drop{border:1px dashed #3a6082;border-radius:12px;padding:9px;background:#081522}.stack{display:flex;flex-direction:column;gap:12px}.event{padding:12px;border:1px solid #203b57;border-radius:13px;background:#091725;margin-top:8px}.empty{padding:36px;text-align:center;color:var(--muted)}.jarvisbar{position:sticky;bottom:12px;z-index:20;margin-top:18px;background:rgba(8,20,35,.98);border:1px solid #2b557b;border-radius:18px;padding:12px;box-shadow:0 18px 60px #0008}.jarvisrow{display:grid;grid-template-columns:auto 1fr auto;gap:10px;align-items:center}.orb{width:42px;height:42px;border-radius:50%;background:radial-gradient(circle at 35% 30%,#d8fbff,#58d9ff 14%,#177ec7 42%,#0b1830 80%);box-shadow:0 0 22px #4bc9ff66}.jarvisbar input,.field{width:100%;padding:12px;border:1px solid #315779;border-radius:11px;background:#06111f;color:white}.reply{padding:8px 52px 0;color:#c7d9e9}.login{max-width:520px;margin:10vh auto}.hidden{display:none!important}.knowledge-grid{display:grid;grid-template-columns:380px 1fr;gap:18px}.fileline{padding:11px;border-bottom:1px solid #1d354e}.fileline b{display:block}@media(max-width:1050px){.metrics{grid-template-columns:repeat(2,1fr)}.grid,.knowledge-grid{grid-template-columns:1fr}.wrap{padding:12px}.jarvisrow{grid-template-columns:auto 1fr}.jarvisrow .btn{grid-column:2}}</style></head><body><div class="wrap"><div class="top"><div class="brand"><div class="logo">PP</div><div><h1>Panther Peptides Command Center</h1><small>Jarvis business operating system · <span id="version"></span></small></div></div><div class="nav"><span id="agentState" class="pill">Jarvis connecting</span><a class="btn" href="/jarvis">Voice Console</a><button class="btn" onclick="load()">Refresh</button></div></div><div id="login" class="card login hidden"><h2>Owner Access</h2><input id="pw" class="field" type="password" placeholder="Owner password"><p><button class="btn primary" onclick="login()">Open Command Center</button></p><div id="loginErr" style="color:var(--red)"></div></div><div id="app"><div class="banner">FOR RESEARCH USE ONLY — NOT FOR HUMAN OR VETERINARY USE · Dashboard defaults to sellable/available inventory. Held and quarantined lots remain recorded but are hidden unless you choose to view them.</div><div class="tabs"><div class="filters"><button id="tabOps" class="btn active" onclick="showTab('ops')">Operations</button><button id="tabKnowledge" class="btn" onclick="showTab('knowledge')">Jarvis Knowledge</button></div></div><div id="ops"><div class="metrics"><div class="metric"><span>Inventory lots</span><b id="lots">—</b></div><div class="metric"><span>Total units</span><b id="units">—</b></div><div class="metric"><span>Held / quarantined</span><b id="quarantine">—</b></div><div class="metric"><span>Available units</span><b id="released">—</b></div><div class="metric"><span>Docs needed</span><b id="missing">—</b></div><div class="metric"><span>Knowledge files</span><b id="kfiles">—</b></div></div><div class="grid"><section class="card"><div class="head"><div><h2>Inventory</h2><div class="filters"><button id="favailable" class="btn active" onclick="setFilter('available')">Available</button><button id="fall" class="btn" onclick="setFilter('all')">All</button><button id="fheld" class="btn" onclick="setFilter('held')">Hold / Quarantine</button></div></div><button class="btn" onclick="importLegacy()">Recover legacy inventory</button></div><div class="tablewrap"><table><thead><tr><th>Product</th><th>Lot / SKU</th><th>Qty</th><th>Status</th><th>Documentation</th><th>Actions</th></tr></thead><tbody id="inventory"></tbody></table></div></section><aside class="stack"><section class="card"><h2>Jarvis Operations</h2><p id="runtime" class="notice">Loading…</p><div id="objectives"></div></section><section class="card"><h2>Business Activity</h2><div id="events"></div></section></aside></div></div><div id="knowledge" class="hidden"><div class="knowledge-grid"><section class="card"><h2>Teach Jarvis</h2><p class="notice">Upload SOPs, product information, supplier notes, policies, research-use documentation, spreadsheets/CSV, PDFs, Markdown, text, code and operating references. Jarvis retrieves relevant material during conversations.</p><form onsubmit="uploadKnowledge(event)"><input id="kfile" class="field" type="file" required><p><input id="kcat" class="field" placeholder="Category e.g. operations, products, suppliers, marketing"></p><p><input id="ktags" class="field" placeholder="Tags, comma separated"></p><button class="btn primary" type="submit">Add to Jarvis Knowledge</button></form><p id="kstats" class="notice"></p></section><section class="card"><div class="head"><h2>Knowledge Library</h2><button class="btn" onclick="loadKnowledge()">Refresh</button></div><div id="klist"></div></section></div></div><div class="jarvisbar"><div class="jarvisrow"><div class="orb"></div><input id="ask" placeholder="Ask Jarvis or give him a business instruction…" onkeydown="if(event.key==='Enter')askJarvis()"><button class="btn primary" onclick="askJarvis()">Ask Jarvis</button></div><div id="reply" class="reply">Jarvis has live business context and retrieves from his persistent knowledge library.</div></div></div></div><script>const $=id=>document.getElementById(id);let data,history=[],filter='available';async function api(url,opt={}){const r=await fetch(url,{...opt,cache:'no-store'}),d=await r.json().catch(()=>({}));if(r.status===401){$('login').classList.remove('hidden');$('app').classList.add('hidden');throw Error('Owner login required')}if(!r.ok)throw Error(d.detail||d.error||`HTTP ${r.status}`);return d}function esc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}function pill(s){return `<span class="pill ${esc(String(s).toLowerCase())}">${esc(s)}</span>`}async function login(){try{await api('/auth/login',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({password:$('pw').value})});$('login').classList.add('hidden');$('app').classList.remove('hidden');load()}catch(e){$('loginErr').textContent=e.message}}function showTab(t){$('ops').classList.toggle('hidden',t!=='ops');$('knowledge').classList.toggle('hidden',t!=='knowledge');$('tabOps').classList.toggle('active',t==='ops');$('tabKnowledge').classList.toggle('active',t==='knowledge');if(t==='knowledge')loadKnowledge()}function setFilter(f){filter=f;['available','all','held'].forEach(x=>$('f'+x).classList.toggle('active',x===f));renderInventory()}async function load(){try{let b=await api('/client/bootstrap');$('version').textContent='v'+b.version;data=await api('/business/dashboard');let s=data.summary;$('lots').textContent=s.lots;$('units').textContent=s.units;$('quarantine').textContent=s.quarantined_units;$('released').textContent=s.released_units;$('missing').textContent=s.lots_missing_or_unknown_docs;$('kfiles').textContent=(data.knowledge||{}).files||0;let rt=data.runtime||{};$('agentState').textContent=rt.worker_alive&&rt.watchdog_alive?'Jarvis online':'Jarvis attention';$('agentState').className='pill '+(rt.worker_alive&&rt.watchdog_alive?'available':'hold');renderInventory();renderOps();renderEvents()}catch(e){if(!String(e.message).includes('Owner login'))console.error(e)}}function visibleRows(){let r=data.inventory||[];if(filter==='available')return r.filter(x=>['available','released','active'].includes(String(x.status).toLowerCase()));if(filter==='held')return r.filter(x=>['hold','quarantine','quarantined','blocked'].includes(String(x.status).toLowerCase()));return r}function renderInventory(){let rows=visibleRows();$('inventory').innerHTML=rows.length?rows.map(x=>{let docs=(x.documents||[]).map(d=>`<div>${esc(d.original_name)} ${pill(d.review_status)}</div>`).join('');let controls=x.legacy?'<span class="muted">Import to manage.</span>':`<div class="actions"><button class="btn green" onclick="setStatus(${x.id},'available')">Available</button><button class="btn amber" onclick="setStatus(${x.id},'hold')">Hold</button><button class="btn amber" onclick="setStatus(${x.id},'quarantine')">Quarantine</button></div><form class="drop" onsubmit="upload(event,${x.id})"><input type="file" required><button class="btn" type="submit">Upload document</button></form>${docs}`;return `<tr><td><b>${esc(x.product)}</b><br><span class="muted">${esc(x.vial_size||'')}</span></td><td>${esc(x.lot_code||'—')}<br><span class="muted">${esc(x.sku||'')}</span></td><td>${esc(x.quantity)}</td><td>${pill(x.status)}</td><td>${pill(x.coa_status||'unknown')}</td><td>${controls}</td></tr>`}).join(''):`<tr><td colspan="6"><div class="empty">No inventory in this view.</div></td></tr>`}function renderOps(){let o=data.objectives||[];$('runtime').textContent=`${o.filter(x=>['running','queued'].includes(x.state)).length} active / queued · ${o.filter(x=>x.state==='blocked').length} blocked`;$('objectives').innerHTML=o.slice(0,7).map(x=>`<div class="event"><b>#${x.id} ${esc(x.title)}</b><small>${esc(x.state)} · step ${esc(x.step)}/${esc(x.max_steps)}</small></div>`).join('')||'<p class="notice">No active objectives.</p>'}function renderEvents(){$('events').innerHTML=(data.events||[]).slice(0,8).map(e=>`<div class="event"><b>${esc(e.title)}</b><div>${esc(e.detail||'')}</div><small>${esc(e.created_at)}</small></div>`).join('')||'<p class="notice">No business events yet.</p>'}async function importLegacy(){if(!confirm('Recover discoverable inventory from the existing Jarvis database?'))return;let d=await api('/business/inventory/import-legacy',{method:'POST'});alert(`Imported ${d.imported} record(s).`);load()}async function upload(ev,id){ev.preventDefault();let f=ev.target.querySelector('input[type=file]').files[0],fd=new FormData();fd.append('file',f);fd.append('kind','coa');let r=await fetch(`/business/inventory/${id}/documents`,{method:'POST',body:fd}),d=await r.json();if(!r.ok)return alert(d.detail||'Upload failed');load()}async function setStatus(id,status){try{await api(`/business/inventory/${id}/status`,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({status})});load()}catch(e){alert(e.message)}}async function askJarvis(){let text=$('ask').value.trim();if(!text)return;$('ask').value='';$('reply').textContent='Jarvis is thinking…';try{let d=await api('/assistant/message',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({message:text,history:history.slice(-10)})});history.push({role:'user',content:text},{role:'assistant',content:d.reply});$('reply').textContent=d.reply+(d.knowledge_used?' · Knowledge consulted':'')}catch(e){$('reply').textContent='Jarvis error: '+e.message}}async function loadKnowledge(){try{let d=await api('/knowledge');$('kstats').textContent=`${d.stats.files} files · ${d.stats.characters.toLocaleString()} indexed characters`;$('klist').innerHTML=(d.items||[]).map(x=>`<div class="fileline"><b>${esc(x.name)}</b><span class="muted">${esc(x.category||'general')} · ${Number(x.characters||0).toLocaleString()} chars · ${esc(x.tags||'')}</span> <button class="btn" onclick="removeKnowledge(${x.id})">Remove</button></div>`).join('')||'<div class="empty">No knowledge uploaded yet.</div>'}catch(e){console.error(e)}}async function uploadKnowledge(ev){ev.preventDefault();let fd=new FormData();fd.append('file',$('kfile').files[0]);fd.append('category',$('kcat').value||'general');fd.append('tags',$('ktags').value||'');let r=await fetch('/knowledge/upload',{method:'POST',body:fd}),d=await r.json();if(!r.ok)return alert(d.detail||'Upload failed');ev.target.reset();loadKnowledge();load()}async function removeKnowledge(id){if(!confirm('Remove this item from Jarvis knowledge?'))return;await api('/knowledge/'+id,{method:'DELETE'});loadKnowledge();load()}load();setInterval(load,12000)</script></body></html>'''